//! Differential tests: the Rust `Tick` port must match the original Solidity library exactly.
//!
//! Vectors are generated by `diff-tests/` (Foundry) from the windv3swap Solidity code:
//! `cd diff-tests && forge test --match-test testGenerateTick`

use std::fs;
use std::path::PathBuf;

use windswap_engine::pool::tick::{self, LiquidityNets, TickInfo, Ticks};
use windswap_engine::{MathError, U256};

fn read_vectors(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../diff-tests/vectors")
        .join(format!("{name}.txt"));
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

fn u(s: &str) -> U256 {
    s.parse().unwrap()
}

fn flag(s: &str) -> bool {
    s == "1"
}

/// Parses a `Tick.Info` state field: `liquidityGross,liquidityNet,stakedLiquidityNet,
/// feeOutside0,feeOutside1,rewardOutside,tickCumulativeOutside,secondsPerLiquidityOutside,
/// secondsOutside,initialized`.
fn parse_state(s: &str) -> TickInfo {
    let f: Vec<&str> = s.split(',').collect();
    assert_eq!(f.len(), 10, "bad state {s}");
    TickInfo {
        liquidity_gross: f[0].parse().unwrap(),
        liquidity_net: f[1].parse().unwrap(),
        staked_liquidity_net: f[2].parse().unwrap(),
        fee_growth_outside0_x128: u(f[3]),
        fee_growth_outside1_x128: u(f[4]),
        reward_growth_outside_x128: u(f[5]),
        tick_cumulative_outside: f[6].parse().unwrap(),
        seconds_per_liquidity_outside_x128: u(f[7]),
        seconds_outside: f[8].parse().unwrap(),
        initialized: flag(f[9]),
    }
}

/// The state of a tick as Solidity reports it: a missing key is the zeroed `Tick.Info`.
fn actual(ticks: &Ticks, tick: i32) -> TickInfo {
    ticks.get(&tick).cloned().unwrap_or_default()
}

/// Compares one case: `Ok` must equal the Solidity output, `Err` must match a Solidity revert.
fn check<T: PartialEq + std::fmt::Debug>(
    name: &str,
    inputs: &[String],
    expected: &Option<Vec<String>>,
    actual: Result<T, MathError>,
    parse: impl Fn(&[String]) -> T,
) {
    match (expected, actual) {
        (Some(out), Ok(got)) => assert_eq!(got, parse(out), "{name} {inputs:?}"),
        (None, Err(_)) => {}
        (Some(out), Err(e)) => {
            panic!("{name} {inputs:?}: Solidity returned {out:?}, Rust errored {e:?}")
        }
        (None, Ok(got)) => panic!("{name} {inputs:?}: Solidity reverted, Rust returned {got:?}"),
    }
}

/// `spacing|ok|maxLiquidity` or `spacing|err`.
#[test]
fn tick_spacing_max_liquidity() {
    let text = read_vectors("tick_spacing_max_liquidity");
    let mut count = 0;
    for line in text.lines().filter(|l| !l.is_empty()) {
        let parts: Vec<String> = line.split('|').map(str::to_owned).collect();
        let spacing: i32 = parts[0].parse().unwrap();
        let (inp, exp) = match parts.get(1).map(String::as_str) {
            Some("ok") => (vec![parts[0].clone()], Some(vec![parts[2].clone()])),
            Some("err") => (vec![parts[0].clone()], None),
            _ => panic!("bad line: {line}"),
        };
        let r = tick::tick_spacing_to_max_liquidity_per_tick(spacing);
        check(
            "tick_spacing_to_max_liquidity_per_tick",
            &inp,
            &exp,
            r,
            |o| o[0].parse().unwrap(),
        );
        count += 1;
    }
    assert!(count > 0, "no vectors in tick_spacing_max_liquidity");
}

/// Replays `tick.txt` in order on a single `Ticks` map. Each line is
/// `op|inputs...|status|outputs...|state` (two states for the read-only growth ops).
/// Every return value and the state of every touched tick must match after each step.
#[test]
fn tick_stateful_replay() {
    let text = read_vectors("tick");
    let mut ticks = Ticks::new();
    let mut counts = std::collections::BTreeMap::<&str, (usize, usize)>::new();

    for (n, line) in text.lines().filter(|l| !l.is_empty()).enumerate() {
        let f: Vec<&str> = line.split('|').collect();
        let op = f[0];
        let state_last = parse_state(f[f.len() - 1]);
        let entry = counts.entry(op).or_insert((0, 0));

        match op {
            "update" => {
                let tick_i: i32 = f[1].parse().unwrap();
                let res = tick::update(
                    &mut ticks,
                    tick_i,
                    f[2].parse().unwrap(),
                    f[3].parse().unwrap(),
                    u(f[4]),
                    u(f[5]),
                    u(f[6]),
                    f[7].parse().unwrap(),
                    f[8].parse().unwrap(),
                    flag(f[9]),
                    f[10].parse().unwrap(),
                );
                match (f[11], res) {
                    ("ok", Ok(flipped)) => {
                        assert_eq!(flipped, flag(f[12]), "line {n}: {line}");
                        entry.0 += 1;
                    }
                    ("err", Err(_)) => entry.1 += 1,
                    (status, res) => panic!("line {n}: {line}: Solidity {status}, Rust {res:?}"),
                }
                assert_eq!(actual(&ticks, tick_i), state_last, "line {n}: {line}");
            }
            "updateStake" => {
                let tick_i: i32 = f[1].parse().unwrap();
                let res = tick::update_stake(&mut ticks, tick_i, f[2].parse().unwrap(), flag(f[3]));
                match (f[4], res) {
                    ("ok", Ok(())) => entry.0 += 1,
                    ("err", Err(_)) => entry.1 += 1,
                    (status, res) => panic!("line {n}: {line}: Solidity {status}, Rust {res:?}"),
                }
                assert_eq!(actual(&ticks, tick_i), state_last, "line {n}: {line}");
            }
            "cross" => {
                let tick_i: i32 = f[1].parse().unwrap();
                assert_eq!(f[8], "ok", "cross has no revert path: {line}");
                let nets = tick::cross(
                    &mut ticks,
                    tick_i,
                    u(f[2]),
                    u(f[3]),
                    u(f[4]),
                    f[5].parse().unwrap(),
                    f[6].parse().unwrap(),
                    u(f[7]),
                );
                let expected = LiquidityNets {
                    liquidity_net: f[9].parse().unwrap(),
                    staked_liquidity_net: f[10].parse().unwrap(),
                };
                assert_eq!(nets, expected, "line {n}: {line}");
                assert_eq!(actual(&ticks, tick_i), state_last, "line {n}: {line}");
                entry.0 += 1;
            }
            "clear" => {
                let tick_i: i32 = f[1].parse().unwrap();
                assert_eq!(f[2], "ok", "clear has no revert path: {line}");
                tick::clear(&mut ticks, tick_i);
                assert_eq!(actual(&ticks, tick_i), state_last, "line {n}: {line}");
                entry.0 += 1;
            }
            "getFee" => {
                let (lo, up): (i32, i32) = (f[1].parse().unwrap(), f[2].parse().unwrap());
                let got = tick::get_fee_growth_inside(
                    &ticks,
                    lo,
                    up,
                    f[3].parse().unwrap(),
                    u(f[4]),
                    u(f[5]),
                );
                assert_eq!(f[6], "ok", "getFeeGrowthInside has no revert path: {line}");
                assert_eq!((u(f[7]), u(f[8])), got, "line {n}: {line}");
                let state_lo = parse_state(f[f.len() - 2]);
                assert_eq!(actual(&ticks, lo), state_lo, "line {n}: {line}");
                assert_eq!(actual(&ticks, up), state_last, "line {n}: {line}");
                entry.0 += 1;
            }
            "getReward" => {
                let (lo, up): (i32, i32) = (f[1].parse().unwrap(), f[2].parse().unwrap());
                let got =
                    tick::get_reward_growth_inside(&ticks, lo, up, f[3].parse().unwrap(), u(f[4]));
                assert_eq!(
                    f[5], "ok",
                    "getRewardGrowthInside has no revert path: {line}"
                );
                assert_eq!(u(f[6]), got, "line {n}: {line}");
                let state_lo = parse_state(f[f.len() - 2]);
                assert_eq!(actual(&ticks, lo), state_lo, "line {n}: {line}");
                assert_eq!(actual(&ticks, up), state_last, "line {n}: {line}");
                entry.0 += 1;
            }
            other => panic!("line {n}: unknown op {other}"),
        }
    }

    for (op, (ok, err)) in &counts {
        eprintln!("tick {op}: ok={ok} err={err}");
    }
    assert!(counts.contains_key("update"), "no update steps replayed");
}
